button.k5:not([aria-pressed=true]):hover:not(:disabled)::before{opacity:.12;transform:none;clip-path:inset(0 0 0 0)}
button.k5[aria-pressed=true]::before{opacity:1;transform:none;clip-path:inset(0 0 0 0)}
button.k5[aria-pressed=true]::before{transition:clip-path .6s cubic-bezier(.3,.7,.2,1) .95s,opacity .2s .95s,filter .5s cubic-bezier(.3,.7,.2,1) .07s}
button.k5.ffdown[aria-pressed=true]:not(:disabled)::before{transform:none;filter:brightness(.6)}
@media (prefers-reduced-motion:reduce){button.k5.ffdraw::after,button.k5.ffdraw .fftx{animation:none}}
.ffrm button.k5.ffdraw::after,.ffrm button.k5.ffdraw .fftx{animation:none}
button.k5.ffpre::after{-webkit-mask-position:0 0;mask-position:0 0}
button.k5.ffpre .fftx{clip-path:inset(-20% 100% -20% -4%)}

.ffslash{--sl:url(data:image/webp;base64,);position:absolute;left:-8%;right:-8%;top:8%;bottom:0;pointer-events:none;z-index:-1;background:var(--c);opacity:.9;-webkit-mask:var(--sl) 100% 0/2500% 100% no-repeat;mask:var(--sl) 100% 0/2500% 100% no-repeat}
.ffslash.ffgo{animation:ffslash .3s steps(25,jump-none) both}
@keyframes ffslash{from{-webkit-mask-position:0 0;mask-position:0 0}to{-webkit-mask-position:100% 0;mask-position:100% 0}}
@media (prefers-reduced-motion:reduce){.ffslash.ffgo{animation:none}}
.ffrm .ffslash.ffgo{animation:none}
.ffslash.ffpre{-webkit-mask-position:0 0;mask-position:0 0}
button:not(:disabled)>.ffslash{display:none}
